$ErrorActionPreference='Continue';$root='F:\JericoEngine\JericoEngine';$base=Join-Path $root 'build\n0-validation\local-packages';$ev=Join-Path $base 'lua-package-negatives';$archive='F:\JericoEngine\Dependencies\archives\lua-5.4.4-source.tar.gz';$hash='2ff89bbea22a7c8b910d6b006f5ba4559edcf468a25537cedf9988ed90f6b450';$url='https://codeload.github.com/lua/lua/tar.gz/refs/tags/v5.4.4';$recipe=Join-Path $root 'cmake\Tools\LocalPackages\Lua\BuildLuaPackage.cmake';if((Get-Location).Path -ne $base){throw 'Unexpected CWD'}
function Invoke-Negative([string]$Name,[string[]]$Vector,[string]$ScriptPath,[string]$ExpectedText,[int]$ExpectedCount){if($Vector.Count -ne $ExpectedCount -or '-P' -notin $Vector -or $ScriptPath -notin $Vector){throw "$Name mode/argv count guard failed"};$rec=[pscustomobject]@{name=$Name;cwd=(Get-Location).Path;executable='cmake.exe';argv=$Vector;argv_count=$Vector.Count;expected_diagnostic=$ExpectedText;started=(Get-Date).ToString('o')};$rec|ConvertTo-Json -Depth 4|Set-Content -LiteralPath (Join-Path $ev "$Name.argv.json") -Encoding utf8;$sw=[Diagnostics.Stopwatch]::StartNew();& cmake.exe @Vector *> (Join-Path $ev "$Name.log");$native=$LASTEXITCODE;$sw.Stop();$found=(Get-Content -LiteralPath (Join-Path $ev "$Name.log") -Raw).Contains($ExpectedText);$res=[pscustomobject]@{name=$Name;exitcode=$native;elapsed_seconds=$sw.Elapsed.TotalSeconds;diagnostic_found=$found;expected_diagnostic=$ExpectedText};$res|ConvertTo-Json -Depth 4|Set-Content -LiteralPath (Join-Path $ev "$Name.result.json") -Encoding utf8;$native|Set-Content -LiteralPath (Join-Path $ev "$Name.exitcode") -NoNewline;$sw.Elapsed.TotalSeconds.ToString('F6',[Globalization.CultureInfo]::InvariantCulture)|Set-Content -LiteralPath (Join-Path $ev "$Name.elapsed.txt") -NoNewline;return $res}
$results=@();$missing=Join-Path $base 'does-not-exist-lua-archive.tar.gz';$bad=Join-Path $base 'lua-neg-bad-hash-source.tar.gz';$cases=@([pscustomobject]@{name='producer-unc';src='\\offline.invalid\share\lua-source.tar.gz';sha=$hash;out=(Join-Path $base 'lua-neg-unc-output');want='must be an absolute local path'},[pscustomobject]@{name='producer-source-missing';src=$missing;sha=$hash;out=(Join-Path $base 'lua-neg-missing-source-output');want='file is missing'},[pscustomobject]@{name='producer-hash-wrong';src=$bad;sha=$hash;out=(Join-Path $base 'lua-neg-hash-output');want='SHA256 mismatch'});foreach($c in $cases){if(Test-Path -LiteralPath $c.out){throw "$($c.name) output preexists"};$v=[string[]]@("-DJE_LUA_SOURCE_ARCHIVE:FILEPATH=$($c.src)","-DJE_LUA_SOURCE_SHA256=$($c.sha)","-DJE_LUA_SOURCE_URL=$url","-DJE_LUA_OUTPUT:PATH=$($c.out)",'-P',$recipe);$r=Invoke-Negative $c.name $v $recipe $c.want 6;$created=Test-Path -LiteralPath $c.out;$r|Add-Member -NotePropertyName output_created -NotePropertyValue $created;if($r.exitcode -eq 0 -or -not $r.diagnostic_found -or $created){throw "$($c.name) did not reject as expected"};$results+=,$r}
$existing=Join-Path $base 'lua-neg-existing-output';if(Test-Path -LiteralPath $existing){throw 'Existing output already exists'};New-Item -ItemType Directory -Path $existing|Out-Null;$sentinel=Join-Path $existing 'sentinel.txt';[IO.File]::WriteAllText($sentinel,'immutable-sentinel');$before=(Get-FileHash -LiteralPath $sentinel -Algorithm SHA256).Hash;$v=[string[]]@("-DJE_LUA_SOURCE_ARCHIVE:FILEPATH=$archive","-DJE_LUA_SOURCE_SHA256=$hash","-DJE_LUA_SOURCE_URL=$url","-DJE_LUA_OUTPUT:PATH=$existing",'-P',$recipe);$r=Invoke-Negative 'producer-output-exists' $v $recipe 'output already exists' 6;$after=(Get-FileHash -LiteralPath $sentinel -Algorithm SHA256).Hash;$r|Add-Member -NotePropertyName sentinel_sha_before -NotePropertyValue $before;$r|Add-Member -NotePropertyName sentinel_sha_after -NotePropertyValue $after;if($r.exitcode -eq 0 -or -not $r.diagnostic_found -or $before -ne $after){throw 'Existing-output negative failed or changed sentinel'};$results+=,$r;@($results)|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $ev 'producer-negative-summary.json') -Encoding utf8;@($results)|ConvertTo-Json -Depth 4
